// Reads both tabs and returns only candidates that are safe to draft now.

const BLOCKED_STATUSES = new Set([
  'dead',
  'invalid',
  'do_not_contact',
  'sent',
  'opt_out',
  'opt-out'
]);
const BLOCKED_DRAFT_STATUSES = new Set(['drafted', 'queued', 'sent']);
const QUALIFIED_VALUES = new Set(['true', 'yes', 'ja', '1', 'qualified', 'ok']);

function clean(v) {
  return String(v ?? '').trim();
}

function lower(v) {
  return clean(v).toLowerCase();
}

function normalizeToken(v) {
  return lower(v).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const normalized = clean(value);
    if (normalized) return normalized;
  }
  return '';
}

function isTruthy(v) {
  return QUALIFIED_VALUES.has(lower(v));
}

function isValidEmail(v) {
  const email = clean(v);
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function looksBlockedStatus(v) {
  const token = normalizeToken(v);
  if (!token) return false;
  if (BLOCKED_STATUSES.has(token)) return true;
  for (const blocked of BLOCKED_STATUSES) {
    if (token.includes(blocked)) return true;
  }
  return false;
}

function looksBlockedDraftStatus(v) {
  const token = normalizeToken(v);
  if (!token) return false;
  if (BLOCKED_DRAFT_STATUSES.has(token)) return true;
  for (const blocked of BLOCKED_DRAFT_STATUSES) {
    if (token.includes(blocked)) return true;
  }
  return false;
}

function inferLanguage(row) {
  const explicit = lower(firstNonEmpty(row.Language, row.language, row.Locale, row.locale));
  if (explicit.startsWith('sv')) return 'sv';
  if (explicit.startsWith('en')) return 'en';

  const country = lower(firstNonEmpty(row.Country, row.country));
  const website = lower(firstNonEmpty(row.Website, row.website));
  const city = lower(firstNonEmpty(row.City, row.city));

  if (country === 'se' || country.includes('sweden') || country.includes('sverige')) return 'sv';
  if (website.endsWith('.se') || website.includes('.se/')) return 'sv';
  if (city) return 'sv';
  return 'en';
}

function candidateIdentity(row) {
  const rowNumber = firstNonEmpty(row.row_number, row.rowNumber, row.RowNumber);
  const candidateId = firstNonEmpty(
    row.CandidateId,
    row.candidateId,
    row.LeadId,
    row.leadId,
    row.LeadID,
    row.lead_id,
    rowNumber ? `row_${rowNumber}` : ''
  );

  return {
    candidateId,
    rowNumber,
  };
}

const candidateRows = (() => {
  try {
    return ($items('Read Outreach Candidates', 0) || []).map((item) => item.json || {});
  } catch (error) {
    return [];
  }
})();

const existingDraftRows = (() => {
  try {
    return ($items('Read Outreach Drafts', 0) || []).map((item) => item.json || {});
  } catch (error) {
    return [];
  }
})();

const existingDraftCandidateIds = new Set();
const existingDraftEmails = new Set();

for (const row of existingDraftRows) {
  const candidateId = firstNonEmpty(row.CandidateId, row.candidateId, row.LeadId, row.leadId);
  const email = lower(firstNonEmpty(row.Email, row.email));

  if (candidateId) existingDraftCandidateIds.add(candidateId);
  if (email) existingDraftEmails.add(email);
}

const seenCandidateIds = new Set();
const seenEmails = new Set();
const eligible = [];

for (const row of candidateRows) {
  const { candidateId, rowNumber } = candidateIdentity(row);
  const email = firstNonEmpty(row.Email, row.email);
  const emailKey = lower(email);
  const status = firstNonEmpty(row.Status, row.status, row.LeadStatus, row.leadStatus);
  const draftStatus = firstNonEmpty(row.DraftStatus, row.draftStatus);
  const explicitQualified = firstNonEmpty(row.Qualified, row.qualified);
  const fallbackQualified = explicitQualified || (clean(row.CandidateReason) || lower(draftStatus) === 'pending' ? 'qualified' : '');
  const isQualified = isTruthy(explicitQualified || fallbackQualified);

  if (!candidateId) continue;
  if (!rowNumber) continue;
  if (!isQualified) continue;
  if (!isValidEmail(email)) continue;
  if (looksBlockedStatus(status)) continue;
  if (looksBlockedDraftStatus(draftStatus)) continue;
  if (existingDraftCandidateIds.has(candidateId)) continue;
  if (emailKey && existingDraftEmails.has(emailKey)) continue;
  if (seenCandidateIds.has(candidateId)) continue;
  if (emailKey && seenEmails.has(emailKey)) continue;

  seenCandidateIds.add(candidateId);
  if (emailKey) seenEmails.add(emailKey);

  eligible.push({
    json: {
      row_number: Number(rowNumber),
      CandidateId: candidateId,
      CompanyName: firstNonEmpty(row.CompanyName, row.companyName, row.Company, row.company, candidateId),
      ContactName: firstNonEmpty(row.ContactName, row.contactName, row.Name, row.name),
      Email: email,
      Website: firstNonEmpty(row.Website, row.website),
      Phone: firstNonEmpty(row.Phone, row.phone, row.phonenumber),
      City: firstNonEmpty(row.City, row.city),
      Industry: firstNonEmpty(row.Industry, row.industry),
      Language: inferLanguage(row),
      Qualified: 'yes',
      Status: status,
      DraftStatus: lower(draftStatus) || 'pending',
      Notes: firstNonEmpty(row.Notes, row.notes)
    }
  });
}

return eligible;

// Build deterministic drafts from boilerplate templates only.

function clean(v) {
  return String(v ?? '').trim();
}

function lower(v) {
  return clean(v).toLowerCase();
}

function nowIso() {
  return new Date().toISOString();
}

function safeIdPart(v) {
  return clean(v).replace(/[^a-zA-Z0-9_-]+/g, '_').replace(/^_+|_+$/g, '') || 'candidate';
}

function makeDraftId(candidateId) {
  return `draft_${safeIdPart(candidateId)}_${Date.now()}`;
}

function pickTemplate(row) {
  const language = lower(row.Language);
  const hasWebsite = clean(row.Website) !== '';
  const hasCity = clean(row.City) !== '';

  if (language === 'sv' && hasWebsite) return 'cold_se_website';
  if (language === 'sv' && hasCity) return 'cold_se_local';
  if (language === 'sv') return 'cold_se_generic';
  return 'cold_en_generic';
}

function renderTemplate(templateKey, row) {
  const companyName = clean(row.CompanyName) || 'ert företag';
  const contactName = clean(row.ContactName);
  const city = clean(row.City);
  const industry = clean(row.Industry);
  const website = clean(row.Website);

  const contactNameOrDefault = templateKey.startsWith('cold_se_')
    ? (contactName || 'där')
    : (contactName || 'there');
  const optionalCityPhrase = city ? ` i ${city}` : '';
  const optionalWebsitePhrase = website ? ` på ${website}` : '';
  const optionalIndustryPhrase = industry ? ` inom ${industry}` : '';

  const templates = {
    cold_se_website: {
      Subject: `En snabb fråga om ${companyName}`,
      Body: [
        `Hej ${contactNameOrDefault},`,
        `Jag såg ${companyName}${optionalCityPhrase} och ville höra en snabb sak.`,
        `Jag noterade att ni redan har en webbplats${optionalWebsitePhrase}, och jag arbetar med att hjälpa företag att förbättra sin synlighet och skapa fler affärsmöjligheter digitalt.`,
        `Om du vill kan jag skicka några korta och konkreta idéer som hade kunnat passa ${companyName}${optionalIndustryPhrase}.`,
        `Vänliga hälsningar`
      ].join('\n\n')
    },
    cold_se_local: {
      Subject: `Kort fråga kring ${companyName}${optionalCityPhrase}`,
      Body: [
        `Hej ${contactNameOrDefault},`,
        `Jag fick upp ögonen för ${companyName}${optionalCityPhrase} och ville bara skicka en snabb fråga.`,
        `Jag hjälper företag att förbättra sin digitala närvaro och göra det tydligare för nya kunder att hitta rätt.`,
        `Om det är intressant skickar jag gärna några enkla och konkreta förslag som hade kunnat passa er.`,
        `Vänliga hälsningar`
      ].join('\n\n')
    },
    cold_se_generic: {
      Subject: `En snabb fråga om ${companyName}`,
      Body: [
        `Hej ${contactNameOrDefault},`,
        `Jag såg ${companyName} och ville höra en snabb sak.`,
        `Jag hjälper företag att förbättra sin digitala synlighet och göra det enklare att få in rätt kunder online.`,
        `Om det känns relevant skickar jag gärna några korta idéer anpassade för er.`,
        `Vänliga hälsningar`
      ].join('\n\n')
    },
    cold_en_generic: {
      Subject: `A quick question about ${companyName}`,
      Body: [
        `Hi ${contactNameOrDefault},`,
        `I came across ${companyName} and wanted to ask a quick question.`,
        `I help businesses improve their digital visibility and make it easier for potential customers to find and trust them online.`,
        `If relevant, I'd be happy to share a few concrete ideas tailored to your business.`,
        `Best regards`
      ].join('\n\n')
    }
  };

  return templates[templateKey] || templates.cold_en_generic;
}

return items.map((item) => {
  const row = item.json || {};
  const draftId = makeDraftId(row.CandidateId);
  const createdAt = nowIso();
  const templateKey = pickTemplate(row);
  const rendered = renderTemplate(templateKey, row);

  return {
    json: {
      DraftId: draftId,
      CandidateId: clean(row.CandidateId),
      CompanyName: clean(row.CompanyName),
      ContactName: clean(row.ContactName),
      Email: clean(row.Email),
      Website: clean(row.Website),
      Phone: clean(row.Phone),
      City: clean(row.City),
      Industry: clean(row.Industry),
      Language: clean(row.Language) || 'en',
      TemplateKey: templateKey,
      Subject: rendered.Subject,
      Body: rendered.Body,
      DraftStatus: 'ready',
      CreatedAt: createdAt,
      UpdatedAt: createdAt,
      SourceWorkflow: 'Workflow 7',
      row_number: Number(row.row_number)
    }
  };
});

function clean(v) {
  return String(v ?? '').trim();
}

function nowIso() {
  return new Date().toISOString();
}

return items
  .filter((item) => clean(item.json?.DraftId) !== '' && item.json?.row_number != null)
  .map((item) => {
    const row = item.json || {};
    return {
      json: {
        row_number: Number(row.row_number),
        DraftStatus: 'drafted',
        LastDraftedAt: clean(row.CreatedAt) || nowIso(),
        LastDraftId: clean(row.DraftId),
        NeedsRescrape: 'no'
      }
    };
  });
